independent-practice.solution:
def bmi(weight_kg, height_m):
    """Return the body mass index for a mass in kg and a height in metres."""
    return weight_kg / (height_m * height_m)

def ticket_price(age):
    """Return the ticket price in pounds for a customer of the given age."""
    if age < 5:
        return 0
    if age < 18:
        return 6
    if age >= 65:
        return 7
    return 11

